(window.webpackJsonp=window.webpackJsonp||[]).push([[15],{339:function(e,t,r){"use strict";r.r(t);var s=r(33),n=Object(s.a)({},function(){var e=this,t=e.$createElement,r=e._self._c||t;return r("ContentSlotsDistributor",{attrs:{"slot-key":e.$parent.slotKey}},[r("h1",{attrs:{id:"ljusbagen-som-stromkalla"}},[r("a",{staticClass:"header-anchor",attrs:{href:"#ljusbagen-som-stromkalla","aria-hidden":"true"}},[e._v("#")]),e._v(" Ljusbågen som strömkälla")]),e._v(" "),r("p",[e._v("Elektrisk ström uppstår när fria elektroner rör sig åt samma håll i en ledare. Elektronerna är bärare av elektriska laddningar. Uppstår ett luftgap bryts elektronflödet och strömmen. Joniseras luftgapet återuppstår elektronflödet så att strömkretsen sluts. Vid joniseringen byter en del elektroner bana och en del övergår till en bana med lägre energiinnehåll. Energin som frigörs bildar elektromagnetiska vågor, vilket ger ett tydligt sken. Ljusskenet som uppstår i luftgapet är en ljusbåge som är av stor betydelse vid bågsvetsning.")]),e._v(" "),r("p",[e._v('Svetsmaskinens tändspänning, (som av säkerhetsskäl är 80 V vid växelströmssvetsning, men max 113 V vid likströmssvetsning), är för låg för att tända ljusbågen med ett överslag. Det krävs ca 5 000 Volt/mm tändspänning i ett luftgap. När elektrodspetsen kortsluts mot arbetsstycket bildas ett elektronmoln runt elektrodspetsen. Då svetsmaskinens tomgångsspänning verkar över luftgapet, kommer elektronerna att "bombardera" arbetsstycket. I detta sammanhang används uttrycket "elektronbombardemang" för att ge ett begrepp om hur stor intensitet som äger rum i denna process. Elektronernas rörelseenergi omsätts i värmeenergi, när rörelsen bromsas upp mot arbetsstycket.')]),e._v(" "),r("p",[e._v("Detta är förklaringen till att arbetsstycket upphettas på den punkt dit elektronbombardemanget riktas. På motsvarande sätt accelerar jonerna som lösgörs från arbetsstycket mot elektrodspetsen, vars temperatur bidrar till att nya elektroner sänds iväg. Eftersom elektronbombardemanget är intensivare än jonbombardemanget uppvärms anoden (+) mer än katoden (-) vid svetsning med likström. Värmefördelningen blir 70% på anoden och 30% på katoden.")]),e._v(" "),r("p",[e._v("När rörelseenergin övergått till värmeenergi upphettas grundmaterialet till smältning och ett smältbad bildas.")]),e._v(" "),r("p",[r("img",{attrs:{src:"https://lernia.itslearning.com/data/1821/556/C__Users_abjorkl2_Desktop_Bild%20sid%2023.jpg",alt:""}})])])},[],!1,null,null,null);t.default=n.exports}}]);